begin;
create extension if not exists pgtap with schema extensions;
select plan(16);

insert into auth.users(id) values('ba8b2af4-a8b5-4b31-9d13-578f15bba739') on conflict (id) do nothing;
insert into public.materials(id,name,manufacturer_name) values('ba8b2af4-a8b5-4b31-9d13-578f15bba741','編集権テスト専用資材','デモ株式会社');
select is((select count(*)::integer from public.materials where id='ba8b2af4-a8b5-4b31-9d13-578f15bba741' and seller_id is not null),0,'initial material has no automatic editing rights');
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated","app_metadata":{"account_type":"seller","seller_id":"33333333-3333-4333-8333-333333333333"}}',true);
set local role authenticated;
select throws_ok($$select public.save_material_page_version('ba8b2af4-a8b5-4b31-9d13-578f15bba741','{"description":"原稿","mainComponents":"","mechanism":"","links":[],"images":[],"usages":[],"timings":[],"certifications":[]}',false)$$,'42501',null,'unverified manufacturer cannot edit');
reset role;
select throws_ok($$select public.set_material_editor_grant('ba8b2af4-a8b5-4b31-9d13-578f15bba741','33333333-3333-4333-8333-333333333333','','ba8b2af4-a8b5-4b31-9d13-578f15bba739')$$,'23514',null,'document reference is mandatory');
select lives_ok($$select public.set_material_editor_grant('ba8b2af4-a8b5-4b31-9d13-578f15bba741','33333333-3333-4333-8333-333333333333','TEST-DOCUMENT-001','ba8b2af4-a8b5-4b31-9d13-578f15bba739')$$,'operator grants documented material rights');
set local role authenticated;
select lives_ok($$select public.save_material_page_version('ba8b2af4-a8b5-4b31-9d13-578f15bba741','{"description":"原稿","mainComponents":"","mechanism":"","links":[],"images":[],"usages":[],"timings":[],"certifications":[]}',false)$$,'documented manufacturer saves a draft');
select throws_ok($$select public.save_material_page_version('ba8b2af4-a8b5-4b31-9d13-578f15bba741','{"description":"競合","mainComponents":"","mechanism":"","links":[],"images":[],"usages":[],"timings":[],"certifications":[]}',false)$$,'40001',null,'stale editor cannot overwrite saved draft');
select lives_ok($$select public.save_material_page_version('ba8b2af4-a8b5-4b31-9d13-578f15bba741','{"description":"公開待ち原稿","mainComponents":"","mechanism":"","links":[],"images":[],"usages":[],"timings":[],"certifications":[]}',true,(select id from public.material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba741' and status='draft'))$$,'draft submitted for expression check');
select isnt((select description from public.materials where id='ba8b2af4-a8b5-4b31-9d13-578f15bba741'),'公開待ち原稿','submission does not change published content');
select set_config('request.jwt.claims','{"sub":"44444444-4444-4444-8444-444444444444","role":"authenticated","app_metadata":{"account_type":"seller","seller_id":"44444444-4444-4444-8444-444444444444"}}',true);
select is((select count(*)::integer from public.material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba741'),0,'another manufacturer cannot read private versions');
select throws_ok($$select public.save_material_page_version('ba8b2af4-a8b5-4b31-9d13-578f15bba741','{"description":"別メーカー","mainComponents":"","mechanism":"","links":[],"images":[],"usages":[],"timings":[],"certifications":[]}',false)$$,'42501',null,'another manufacturer cannot edit');
select is(has_function_privilege('authenticated','app.save_material_page_version(uuid,uuid,jsonb,boolean)','execute'),false,'internal save cannot bypass public validation');
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select is((select count(*)::integer from public.material_page_versions),0,'anonymous cannot read unpublished versions');
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated","app_metadata":{"account_type":"seller","seller_id":"33333333-3333-4333-8333-333333333333"}}',true);
reset role;
select lives_ok($$select public.revoke_material_editor_grant('ba8b2af4-a8b5-4b31-9d13-578f15bba741','ba8b2af4-a8b5-4b31-9d13-578f15bba739')$$,'operator revokes editing rights');
select is((select count(*)::integer from public.material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba741' and status in ('draft','pending')),0,'revocation withdraws working versions');
select throws_ok($$select public.review_material_page_version((select id from public.material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba741' and status='withdrawn'),'ba8b2af4-a8b5-4b31-9d13-578f15bba739',true,'')$$,'23505',null,'withdrawn version cannot be published');
set local role authenticated;
select throws_ok($$select public.save_material_page_version('ba8b2af4-a8b5-4b31-9d13-578f15bba741','{"description":"原稿","mainComponents":"","mechanism":"","links":[],"images":[],"usages":[],"timings":[],"certifications":[]}',false)$$,'42501',null,'revoked manufacturer cannot edit');
reset role;
select * from finish();
rollback;
